"""Exact finite impact integrals and optional Arb evaluation.

J_m(b) = integral_4^infinity K0(b*sqrt(t))*sin(m*phi(t)) dt, with
cos(phi)=8/t-1. Every mode is pi*(exp(-2*b)*P(b)+E1(2*b)*Q(b)),
where b*P and Q have rational coefficients. See docs/21_closed_form_impact.md.
No optimization constraints or existing numerical projectors are changed.
"""
from dataclasses import dataclass
from fractions import Fraction
from functools import lru_cache
from numbers import Integral

from .amplitudes import basis_labels

F = Fraction
NORMALIZATIONS = ("none", "threshold", "kernel_mass")


def _rational(value):
    if isinstance(value, bool):
        raise ValueError("Use finite real rational or decimal inputs")
    if isinstance(value, F):
        return value
    try:
        return F(str(value))
    except (ValueError, TypeError, ZeroDivisionError) as error:
        raise ValueError("Use finite real rational or decimal inputs") from error


def _degree(value):
    if not isinstance(value, Integral) or isinstance(value, bool) or value < 1:
        raise ValueError("degree must be a positive integer")
    return int(value)


def _trim(values):
    values = list(values)
    while len(values) > 1 and values[-1] == 0:
        values.pop()
    return tuple(values)


def _at(values, index):
    return values[index] if 0 <= index < len(values) else F(0)


def _horner(values, point):
    out = F(0)
    for value in reversed(values):
        out = out*point + value
    return out


@dataclass(frozen=True)
class ImpactClosedForm:
    """pi*(exp(-2*b)*P(b)+E1(2*b)*Q(b)); arrays use ascending powers.

    ``p_numerator`` stores b*P(b), so it also represents the possible 1/b
    term without floating-point Laurent coefficients. ``q`` stores Q(b).
    """
    p_numerator: tuple[Fraction, ...]
    q: tuple[Fraction, ...]

    def rational_values(self, b):
        """Return exact P(b), Q(b), evaluating all polynomial cancellation first."""
        b = _rational(b)
        if b <= 0:
            raise ValueError("A positive impact parameter is required")
        return _horner(self.p_numerator, b)/b, _horner(self.q, b)

    def as_dict(self):
        return dict(p_numerator=[str(v) for v in self.p_numerator],
                    q=[str(v) for v in self.q],
                    convention="Ascending powers; P(b)=poly(p_numerator,b)/b; Q(b)=poly(q,b)")


@lru_cache(maxsize=None)
def _laplace_forms(degree):
    # L_k/pi = exp(-2b)*P_k + E1(2b)*Q_k.
    forms = [ImpactClosedForm((F(1),), (F(-2),))]
    for k in range(1, degree):
        old = forms[-1]
        qnew = [F(0)]*(len(old.q)+2)
        for j, value in enumerate(old.q):
            qnew[j+2] = value/F((j+2)**2)
        pnew = [F(0)]*(2*k)
        for j in range(2*k-1, -1, -1):
            rhs = (_at(old.p_numerator, j+1)-2*_at(qnew, j+1)
                   + 2*(j+2)*_at(qnew, j+2))
            pnew[j] = (rhs+(4*j+6)*_at(pnew, j+1)
                       -(j+2)**2*_at(pnew, j+2))/4
        qnew[0] = (old.p_numerator[0]-_at(pnew, 1)+2*pnew[0])/2
        forms.append(ImpactClosedForm(_trim([F(0), *pnew]), _trim(qnew)))
    return tuple(forms)


def laplace_integral_closed_forms(degree):
    """Exact forms of L_k=integral sqrt(t-4)*t^(-k)*K0(b*sqrt(t)) dt, k=1..N."""
    return _laplace_forms(_degree(degree))


def _combine(forms, weights):
    p = [F(0)]*max(len(f.p_numerator) for f in forms)
    q = [F(0)]*max(len(f.q) for f in forms)
    for form, weight in zip(forms, weights):
        for j, value in enumerate(form.p_numerator):
            p[j] += weight*value
        for j, value in enumerate(form.q):
            q[j] += weight*value
    return ImpactClosedForm(_trim(p), _trim(q))


@lru_cache(maxsize=None)
def _impact_forms(degree):
    laplace = _laplace_forms(degree)
    previous, current = (F(0),), (F(1),)
    result = []
    for mode in range(1, degree+1):
        result.append(_combine(laplace[:mode], [4*v for v in current]))
        # U_(n+1)(8v-1)=(16v-2)U_n(8v-1)-U_(n-1)(8v-1).
        following = [F(0)]*(len(current)+1)
        for j, value in enumerate(current):
            following[j] -= 2*value
            following[j+1] += 16*value
        for j, value in enumerate(previous):
            following[j] -= value
        previous, current = current, _trim(following)
    return tuple(result)


def impact_integral_closed_forms(degree):
    """Return immutable exact rational forms for J_1,...,J_degree."""
    return _impact_forms(_degree(degree))


def impact_profile_closed_forms(coefficients, degree):
    """Form the three profiles directly from exact decimal amplitude coefficients.

    Combining the rational P/Q polynomials before transcendental evaluation
    avoids cancellation introduced by separately rounded mode values.
    """
    degree = _degree(degree)
    coefficients = tuple(_rational(v) for v in coefficients)
    labels = basis_labels(degree)
    if len(coefficients) != len(labels):
        raise ValueError("Incorrect amplitude coefficient count")
    sine = [[F(0)]*degree for _ in range(3)]
    for value, (kind, n, m) in zip(coefficients, labels):
        wn, wm = n*(-1)**(n+1), m*(-1)**(m+1)
        if kind == "double_s_tu":
            sine[0][m-1] += 3*wn*value
            for row in sine:
                row[n-1] += wm*value
        elif kind == "double_tu":
            for row, sign in zip(sine, (1, -1, 1)):
                row[m-1] += F(sign*wn, 2)*value
                row[n-1] += F(sign*wm, 2)*value
    sine = tuple(tuple(row) for row in sine)
    forms = impact_integral_closed_forms(degree)
    return tuple(_combine(forms, row) for row in sine), sine


def impact_ratio_derivative_numerator(form):
    """Exact polynomial R with (H/Q)'=pi*exp(-2b)*R/(b^2*Q^2).

    H=pi*(exp(-2b)*P+E1(2b)*Q). The identity is used only where Q != 0.
    Positive roots of R and Q partition the half-line into intervals on which
    H/Q is monotone. This helper does not itself isolate roots or certify a
    whole-half-line sign, especially at common zeros of P and Q.
    """
    a, q = form.p_numerator, form.q

    def multiply(left, right):
        out = [F(0)]*(len(left)+len(right)-1)
        for j, x in enumerate(left):
            for k, y in enumerate(right):
                out[j+k] += x*y
        return out

    def derivative(values):
        return [j*v for j, v in enumerate(values) if j] or [F(0)]

    # R=b*(Q A'-Q' A-2 Q A-Q^2)-Q A, where A=b*P.
    qa = multiply(q, a)
    terms = [(1, multiply(q, derivative(a))),
             (-1, multiply(derivative(q), a)),
             (-2, qa), (-1, multiply(q, q))]
    result = [F(0)]*(1+max(len(values) for _, values in terms))
    for sign, values in terms:
        for j, value in enumerate(values):
            result[j+1] += sign*value
    for j, value in enumerate(qa):
        result[j] -= value
    return _trim(result)


def _evaluate_arb(forms, b, normalization, precision_bits,
                  target_accuracy_bits, max_precision_bits):
    from flint import arb, ctx

    b = _rational(b)
    if b <= 0:
        raise ValueError("A positive impact parameter is required")
    if normalization not in NORMALIZATIONS:
        raise ValueError(f"normalization must be one of {NORMALIZATIONS}")
    for value, name in ((precision_bits, "precision_bits"),
                        (target_accuracy_bits, "target_accuracy_bits"),
                        (max_precision_bits, "max_precision_bits")):
        if not isinstance(value, Integral) or isinstance(value, bool) or value < 1:
            raise ValueError(f"{name} must be a positive integer")
    if precision_bits < 64 or max_precision_bits < precision_bits:
        raise ValueError("Require 64 <= precision_bits <= max_precision_bits")
    rational_pairs = [form.rational_values(b) for form in forms]

    def ball(value):
        return arb(value.numerator)/value.denominator

    def interval(value):
        return dict(lower_rational=str(value.lower().fmpq()),
                    upper_rational=str(value.upper().fmpq()), ball=str(value),
                    midpoint_approximate=float(value.mid()),
                    radius_upper_approximate=float(value.rad().upper()),
                    relative_accuracy_bits=None if value.is_zero() else int(value.rel_accuracy_bits()),
                    exact_zero=bool(value.is_zero()))

    old_precision = ctx.prec
    used = int(precision_bits)
    try:
        while True:
            ctx.prec = used
            bb = ball(b)
            # U(1,1,x)=exp(x)*E1(x), evaluated in its scaled form.
            scaled_e1 = (2*bb).hypgeom_u(1, 1)
            if normalization == "none":
                scale = arb.pi()*(-2*bb).exp()
            elif normalization == "threshold":
                scale = bb**2/2
            else:
                scale = arb.pi()*bb/(4*(2*bb).bessel_k(1, scaled=True))
            values = [arb(0) if p == 0 and q == 0
                      else scale*(ball(p)+ball(q)*scaled_e1)
                      for p, q in rational_pairs]
            finite = all(value.is_finite() for value in values)
            accurate = finite and all(value.is_zero() or value.rel_accuracy_bits() >= target_accuracy_bits
                                      for value in values)
            if accurate or used == max_precision_bits:
                break
            used = min(2*used, int(max_precision_bits))
        if not finite:
            raise ArithmeticError("Arb evaluation remained non-finite at the precision limit")
        return dict(b=str(b), normalization=normalization,
            normalization_formula={"none": "J_m or H_I",
                "threshold": "b^2 exp(2b)/(2pi) times J_m or H_I",
                "kernel_mass": "(J_m or H_I)/M(b), M(b)=4 K1(2b)/b"}[normalization],
            precision_bits_requested=int(precision_bits), precision_bits_used=used,
            target_accuracy_bits=int(target_accuracy_bits), accuracy_target_met=bool(accurate),
            rigorous_enclosures=True, enclosures=[interval(value) for value in values],
            coefficient_semantics="Exact supplied rational/decimal values; float inputs mean str(value).",
            method="Exact rational P,Q followed by Arb U(1,1,2b) and explicit positive normalization.")
    finally:
        ctx.prec = old_precision


def evaluate_impact_integrals_arb(b, degree, *, normalization="none", precision_bits=160,
                                  target_accuracy_bits=80, max_precision_bits=2560):
    """Rigorous J_m enclosures, with adaptive precision for cancellation.

    ``kernel_mass`` matches the probability-kernel normalization J_m/M used
    by impact_constraints.py. ``threshold`` tends to m as b tends to infinity.
    If the accuracy cap is reached, the still-rigorous enclosure is returned
    with accuracy_target_met=False; no sign is inferred from its midpoint.
    """
    degree = _degree(degree)
    report = _evaluate_arb(impact_integral_closed_forms(degree), b, normalization,
                           precision_bits, target_accuracy_bits, max_precision_bits)
    report["degree"] = degree
    report["modes"] = [dict(mode=i, enclosure=value)
                       for i, value in enumerate(report.pop("enclosures"), 1)]
    return report


def certify_impact_profile_closed_form(b, coefficients, degree, *, normalization="none",
                                       precision_bits=160, target_accuracy_bits=80,
                                       max_precision_bits=2560):
    """Certify one b value for all three exact-decimal amplitude profiles.

    Negative upper endpoints exclude all-energy/all-spin unitarity of this
    amplitude. Positive point evaluations do not certify the condition for all b.
    """
    forms, sine = impact_profile_closed_forms(coefficients, degree)
    report = _evaluate_arb(forms, b, normalization, precision_bits,
                           target_accuracy_bits, max_precision_bits)
    channels = []
    for iso, enclosure in enumerate(report.pop("enclosures")):
        lower, upper = F(enclosure["lower_rational"]), F(enclosure["upper_rational"])
        sign = "negative" if upper < 0 else ("positive" if lower > 0 else "undetermined")
        channels.append(dict(isospin=iso, enclosure=enclosure, sign=sign,
            excludes_all_energy_all_spin_unitarity=bool(upper < 0)))
    report.update(degree=int(degree), channels=channels,
        exact_sine_coefficients=[[str(v) for v in row] for row in sine],
        exact_closed_forms=[form.as_dict() for form in forms],
        scope="A certified value at one b only; neither all-b positivity nor continuum unitarity is certified.")
    return report
